-- Idempotent Wordstat calm-music seed, part 1/12 (100 approved queries).
-- Source checked on 2026-09-26; curated range 50-2000.
BEGIN;
ON CONFLICT (normalized_query) DO UPDATE SET
  frequency = COALESCE(public.seo_queries.frequency, EXCLUDED.frequency),
  frequency_checked_at = COALESCE(public.seo_queries.frequency_checked_at, EXCLUDED.frequency_checked_at),
  intent = COALESCE(public.seo_queries.intent, EXCLUDED.intent),
  recommended_format = COALESCE(public.seo_queries.recommended_format, EXCLUDED.recommended_format),
  audio_fit = COALESCE(public.seo_queries.audio_fit, EXCLUDED.audio_fit);
COMMIT;
